export function visibleReportCenter(report, viewportTop, viewportBottom) {
    const top = Math.max(report.top, viewportTop);
    const bottom = Math.min(report.bottom, viewportBottom);
    if (bottom <= top) return report.height / 2;
    return (top + bottom) / 2 - report.top;
}

function createLoader() {
    const loader = document.createElement('div');
    loader.className = 'traffic-loader';
    loader.innerHTML = `
        <div class="traffic-loader__content" role="status">
            <span class="traffic-loader__spinner" aria-hidden="true"></span>
            <p>Loading traffic insights…</p>
        </div>
    `;
    return loader;
}

export function initScript(trafficContainer) {
    if (!trafficContainer) return () => {};

    const isDarkMode = document.body.classList.contains('dark-mode');
    const iframeSrc = isDarkMode
        ? 'https://lookerstudio.google.com/embed/reporting/fa45582a-0947-4aa9-a259-df74aaaf38a1/page/EkW8D?hl=en'
        : 'https://lookerstudio.google.com/embed/reporting/4a46ee2f-a660-48a5-8717-eea7cd8eaaa2/page/EkW8D?hl=en';

    trafficContainer.innerHTML = '';
    trafficContainer.classList.add('traffic-report-wrapper');

    const loader = createLoader();
    trafficContainer.appendChild(loader);

    const iframe = document.createElement('iframe');
    iframe.id = 'trafficReportFrame';
    iframe.src = iframeSrc;
    iframe.style.width = '100%';
    iframe.style.border = '0';
    iframe.allowFullscreen = true;
    iframe.sandbox = 'allow-storage-access-by-user-activation allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox';

    let frame = 0;
    let removalTimer = 0;
    let previousCenter = null;
    const header = document.querySelector('.container > .header');

    function adjustIframeHeight() {
        const height = `${iframe.clientWidth * (1068 / 600)}px`;
        if (iframe.style.height !== height) iframe.style.height = height;
    }

    // Follow the visible report area during entrance motion and scrolling.
    // Stop measuring as soon as the embedded report finishes loading.
    function positionLoader() {
        const viewport = window.visualViewport;
        let top = viewport?.offsetTop || 0;
        const bottom = top + (viewport?.height || window.innerHeight);
        if (header && /^(fixed|sticky)$/.test(getComputedStyle(header).position)) {
            const bounds = header.getBoundingClientRect();
            if (bounds.top <= top && bounds.bottom > top) top = bounds.bottom;
        }
        const center = visibleReportCenter(trafficContainer.getBoundingClientRect(), top, bottom);
        if (center !== previousCenter) {
            loader.style.setProperty('--traffic-loader-center', `${center}px`);
            previousCenter = center;
        }
        frame = requestAnimationFrame(positionLoader);
    }

    function onLoad() {
        cancelAnimationFrame(frame);
        iframe.classList.add('traffic-report-frame-ready');
        loader.classList.add('traffic-loader--hidden');
        removalTimer = setTimeout(() => loader.remove(), 600);
        adjustIframeHeight();
    }

    iframe.addEventListener('load', onLoad);
    trafficContainer.appendChild(iframe);
    adjustIframeHeight();
    const observer = new ResizeObserver(adjustIframeHeight);
    observer.observe(trafficContainer);
    positionLoader();

    return () => {
        cancelAnimationFrame(frame);
        clearTimeout(removalTimer);
        observer.disconnect();
        iframe.removeEventListener('load', onLoad);
    };
}
